// Gmail's message shape differs from the IMAP node's. Rather than teach Resolve
// Report Metadata two shapes, normalise here - one adapter, and the node that does
// the attribution keeps a single input contract.
//
// Resolve Report Metadata reads: headers, to, cc, from, text, html, date, messageId.
const g = $input.item.json;
const h = g.headers || {};

return {
  json: {
    headers: h,
    to: g.to || h.to || null,
    cc: g.cc || h.cc || null,
    from: g.from || h.from || null,
    // `simple: false` on the Gmail node is what makes these available. The download
    // link lives in the body, and without it there is nothing to resolve.
    text: g.text || '',
    html: g.textAsHtml || g.html || '',
    date: g.date || h.date || null,
    messageId: g.messageId || h['message-id'] || null,
    // The Gmail API id, carried through so the cleanup step can trash this exact
    // message without having to search for it again.
    gmail_id: g.id || null,
    subject: g.subject || h.subject || null,
  },
};

// ONE report per execution. `Find Unprocessed Reports` is capped at a single email,
// so the metadata is unambiguous and no paired-item lookup is needed anywhere in
// this graph. That is deliberate, not a shortcut: the only reason this workflow ever
// raised "Paired item data for item from node 'Download Report File' is unavailable"
// is that when n8n recovers a CRASHED run it replaces every node's output with a stub
// that carries no pairedItem. Reading .first() removes the dependency entirely, so a
// recovered or retried run behaves like a fresh one.
//
// This node returns a SINGLE item holding the whole report rather than one item per
// row. n8n retains the input and output of every node run for the life of the
// execution, so one item per row meant the report was held in memory five or six
// times over. A 60-email backlog of ~200,000 rows is what exhausted the heap on
// 2026-09-08 and put the workflow in a crash loop.
const meta = $('Resolve Report Metadata').first().json;
const rowKeyField = meta.row_key_field;

// A natural key that REPEATS inside one file is disambiguated by position. On
// 2026-09-12 a local Lead Status export carried two rows with the same Quote #;
// ON CONFLICT DO NOTHING kept one, the row-count assertion failed (4499 vs 4498),
// the email stayed in the inbox, and the sweep re-failed on it every 2 minutes for
// two days - blocking every older report behind it and every dbt rebuild. Raw must
// carry what the source sent, so the second occurrence lands as `<key>#<position>`.
// Position is stable across re-ingests of the same file, so idempotency holds.
// dbt joins on the Quote # inside row_data, never on row_key, so nothing downstream
// sees the suffix.
const seenKeys = new Set();

const payload = $input.all().map((item, i) => {
  const row = { ...item.json };

  let rowKey = rowKeyField ? String(row[rowKeyField] ?? '').trim() : '';

  if (!rowKey) {
    // NO NATURAL KEY - the payments report is the case this exists for. SmartMoving
    // emits no Quote #-unique column there: one customer can pay twice against the
    // same quote on the same day, and two rows can be byte-identical.
    //
    // THE KEY IS THE ROW'S POSITION IN THE FILE, AND NOTHING ELSE. It used to be
    // position + a content hash; the hash was not stable across re-ingests, so
    // ON CONFLICT never matched and 13 payments generations landed up to six times
    // over (measured 2026-09-09). Position is stable, which is exactly the property
    // idempotency needs.
    rowKey = '__row' + String(i).padStart(6, '0');
  } else if (seenKeys.has(rowKey)) {
    rowKey = rowKey + '#' + String(i).padStart(6, '0');
  }
  seenKeys.add(rowKey);

  return {
    source_instance_id: meta.source_instance_id,
    entity_id: meta.entity_id,
    report_generated_at: meta.report_generated_at,
    row_key: rowKey,
    row_data: row,
    _source_email: meta.message_id,
  };
});

return [{
  json: {
    target_table: meta.target_table,
    report_type: meta.report_type,
    source_instance_id: meta.source_instance_id,
    report_generated_at: meta.report_generated_at,
    row_count: payload.length,
    // Serialised here so the Postgres node passes it as one bind parameter.
    rows: JSON.stringify(payload),
  },
}];

// One item per DISTINCT report present in THIS execution.
//
// The IMAP trigger does not deliver one email per execution. When SmartMoving sends
// all eight scheduled reports at once they arrive together, and on 2026-08-13 seven
// reports were processed across five executions - several sharing a run.
//
// The previous verification read $('Resolve Report Metadata').first(), so exactly one
// report per execution was row-count checked and every other one landed unverified.
// That is the precise situation a truncated report slips through: the rows are in the
// table, nothing failed, and no one knows the count was short.
const seen = new Map();

for (const item of $('Resolve Report Metadata').all()) {
  const m = item.json || {};
  if (!m.is_valid || !m.target_table) continue;

  // A report is identified by where it lands, for whom, and when it was generated -
  // the same three columns as the landing table's primary key.
  const key = m.source_instance_id + '|' + m.target_table + '|' + m.report_generated_at;
  if (seen.has(key)) continue;

  seen.set(key, {
    report_type: m.report_type,
    target_table: m.target_table,
    source_instance_id: m.source_instance_id,
    report_generated_at: m.report_generated_at,
    expected_records: m.expected_records,
  });
}

return Array.from(seen.values()).map(json => ({ json }));

const r = $input.item.json;
const meta = $('Collect Reports To Verify').item.json;

const expected = (r.expected_records === null || r.expected_records === undefined)
  ? null
  : Number(r.expected_records);
const landed = Number(r.landed_records);

// Runs once per REPORT now, not once per execution. SmartMoving states the record
// count in the email body; a mismatch means rows were dropped between the download
// and the insert. Throwing routes this to datawarehouse_error_handler and Slack: a
// truncated report that lands quietly is far worse than one that fails loudly,
// because every downstream number silently becomes wrong.
if (expected !== null && landed !== expected) {
  throw new Error(
    'Row count mismatch for ' + meta.report_type + ' / ' + meta.source_instance_id +
    ': SmartMoving reported ' + expected + ' records, ' + landed + ' landed. ' +
    'Do not trust downstream numbers for this report until resolved.'
  );
}

return { json: {
  report_type: meta.report_type,
  source_instance_id: meta.source_instance_id,
  report_generated_at: meta.report_generated_at,
  expected_records: expected,
  landed_records: landed,
  verified: true,
} };

// One item per DISTINCT email that was successfully processed in THIS execution.
//
// Runs immediately after the row-count check, and BEFORE the dbt rebuild. That order
// is the important part. Cleanup used to sit behind Assert Rebuild Succeeded, so any
// failure anywhere downstream left the email sitting in the inbox - and the sweep
// picks up everything still in the inbox. One crash on 2026-09-08 therefore fed a
// bigger batch into the next run, which crashed harder, for 24 hours.
//
// The row-count assertion is the right place to stop: it proves the email was fully
// consumed and every row SmartMoving announced is in raw. Whether dbt then rebuilds
// successfully is a separate concern - the rows are landed either way, and
// re-downloading the email would not fix a broken model. A failed rebuild still
// throws and still alerts through datawarehouse_error_handler.
const seen = new Set();
const out = [];

for (const item of $('Resolve Report Metadata').all()) {
  const m = item.json || {};
  if (!m.is_valid || !m.rfc822_msgid) continue;
  if (seen.has(m.rfc822_msgid)) continue;
  seen.add(m.rfc822_msgid);
  out.push({ json: {
    rfc822_msgid: m.rfc822_msgid,
    report_type: m.report_type,
    source_instance_id: m.source_instance_id,
  } });
}

return out;

const r = $input.first().json;
const out = String(r.stdout || '') + '\n' + String(r.stderr || '');
const code = Number(r.code ?? r.exitCode ?? 0);

// Same guard as the nightly build. The SSH node reports the remote exit status but
// does not fail the workflow on it, so without this a broken rebuild leaves the
// report looking ingested while core and serving still hold yesterday's numbers.
const m = (out.match(/Done\. PASS=(\d+) WARN=(\d+) ERROR=(\d+) SKIP=(\d+)/) || null);

if (code !== 0 || !m) {
  throw new Error(
    'dbt rebuild FAILED after ingesting a report (exit ' + code + '). The rows are ' +
    'landed but core and serving have NOT been refreshed.\n\n' + out.slice(-3000)
  );
}

const [, pass, warn, error, skip] = m.map(Number);
if (error > 0 || skip > 0) {
  throw new Error(
    'dbt rebuild finished with ERROR=' + error + ' SKIP=' + skip + '.\n\n' + out.slice(-3000)
  );
}

return [{ json: { ok: true, pass, warn, rebuilt_at: new Date().toISOString() } }];
